public void handleEvent(StreamSourceChannel channel) {

            HttpResponseBuilder builder = pendingResponse;
            final PooledByteBuffer pooled = bufferPool.allocate();
            final ByteBuffer buffer = pooled.getBuffer();
            boolean free = true;

            try {

                if (builder == null) {
                    //read ready when no request pending
                    buffer.clear();
                    try {
                        int res = channel.read(buffer);
                         if(res == -1) {
                            UndertowLogger.CLIENT_LOGGER.debugf("Connection to %s was closed by the target server", connection.getPeerAddress());
                            safeClose(HttpClientConnection.this);
                        } else if(res != 0) {
                             UndertowLogger.CLIENT_LOGGER.debugf("Target server %s sent unexpected data when no request pending, closing connection", connection.getPeerAddress());
                             safeClose(HttpClientConnection.this);
                        }
                        //otherwise it is a spurious notification
                    } catch (IOException e) {
                        if (UndertowLogger.CLIENT_LOGGER.isDebugEnabled()) {
                            UndertowLogger.CLIENT_LOGGER.debugf(e, "Connection closed with IOException");
                        }
                        safeClose(connection);
                    }
                    return;
                }
                final ResponseState state = builder.getParseState();
                int res;
                do {
                    buffer.clear();
                    try {
                        res = channel.read(buffer);
                    } catch (IOException e) {
                        if (UndertowLogger.CLIENT_LOGGER.isDebugEnabled()) {
                            UndertowLogger.CLIENT_LOGGER.debugf(e, "Connection closed with IOException");
                        }
                        try {
                            if (currentRequest != null) {
                                currentRequest.setFailed(e);
                                currentRequest = null;
                            }
                            pendingResponse = null;
                        } finally {
                            safeClose(channel, HttpClientConnection.this);
                        }
                        return;
                    }

                    if (res == 0) {
                        if (!channel.isReadResumed()) {
                            channel.getReadSetter().set(this);
                            channel.resumeReads();
                        }
                        return;
                    } else if (res == -1) {
                        channel.suspendReads();
                        try {
                            // Cancel the current active request
                            if (currentRequest != null) {
                                currentRequest.setFailed(new IOException(MESSAGES.connectionClosed()));
                                currentRequest = null;
                            }
                            pendingResponse = null;
                        } finally {
                            safeClose(HttpClientConnection.this);
                        }
                        return;
                    }

                    buffer.flip();

                    ResponseParser.INSTANCE.handle(buffer, state, builder);
                    if (buffer.hasRemaining()) {
                        free = false;
                        pushBackStreamSourceConduit.pushBack(new PooledAdaptor(pooled));
                        pushBackStreamSourceConduit.wakeupReads();
                    }

                } while (!state.isComplete());

                final ClientResponse response = builder.build();

                String connectionString = response.getResponseHeaders().getFirst(Headers.CONNECTION);

                //check if an upgrade worked
                if (anyAreSet(HttpClientConnection.this.state, UPGRADE_REQUESTED)) {
                    if ((connectionString == null || !Headers.UPGRADE.equalToString(connectionString)) && !response.getResponseHeaders().contains(Headers.UPGRADE)) {
                        if(!currentRequest.getRequest().getMethod().equals(Methods.CONNECT) || response.getResponseCode() != 200) { //make sure it was not actually a connect request
                            //just unset the upgrade requested flag
                            HttpClientConnection.this.state &= ~UPGRADE_REQUESTED;
                        }
                    }
                }
                boolean close = false;
                if(connectionString != null) {
                    if (Headers.CLOSE.equalToString(connectionString)) {
                        close = true;
                    } else if(!response.getProtocol().equals(Protocols.HTTP_1_1)) {
                        if(!Headers.KEEP_ALIVE.equalToString(connectionString)) {
                            close = true;
                        }
                    }
                } else if(!response.getProtocol().equals(Protocols.HTTP_1_1)) {
                    close = true;
                }
                if(close) {
                    HttpClientConnection.this.state |= CLOSE_REQ;
                    //we are going to close, kill any queued connections
                    HttpClientExchange ex = pendingQueue.poll();
                    while (ex != null) {
                        ex.setFailed(new IOException(UndertowClientMessages.MESSAGES.connectionClosed()));
                        ex = pendingQueue.poll();
                    }
                }
                if(response.getResponseCode() == StatusCodes.SWITCHING_PROTOCOLS && Http2Channel.CLEARTEXT_UPGRADE_STRING.equals(response.getResponseHeaders().getFirst(Headers.UPGRADE))) {
                    //http2 upgrade

                    http2UpgradeReceived = true;
                    if(currentRequest.isRequestDataSent()) {
                        doHttp2Upgrade();
                    }
                } else if (builder.getStatusCode() == StatusCodes.CONTINUE) {
                    pendingResponse = new HttpResponseBuilder();
                    currentRequest.setContinueResponse(response);
                } else {
                    prepareResponseChannel(response, currentRequest);
                    channel.getReadSetter().set(null);
                    channel.suspendReads();
                    pendingResponse = null;
                    currentRequest.setResponse(response);
                    if(response.getResponseCode() == StatusCodes.EXPECTATION_FAILED) {
                        if(HttpContinue.requiresContinueResponse(currentRequest.getRequest().getRequestHeaders())) {
                            HttpClientConnection.this.state |= CLOSE_REQ;
                            ConduitStreamSinkChannel sinkChannel = HttpClientConnection.this.connection.getSinkChannel();
                            sinkChannel.shutdownWrites();
                            if(!sinkChannel.flush()) {
                                sinkChannel.setWriteListener(ChannelListeners.flushingChannelListener(null, null));
                                sinkChannel.resumeWrites();
                            }
                            if(currentRequest != null) {
                                //we need the null check as flushing the response may have terminated the request
                                currentRequest.terminateRequest();
                            }
                        }
                    }
                }


            } catch (Throwable t) {
                UndertowLogger.CLIENT_LOGGER.exceptionProcessingRequest(t);
                safeClose(connection);
                if(currentRequest != null) {
                    currentRequest.setFailed(new IOException(t));
                }
            } finally {
                if (free) {
                    pooled.close();
                    pooledBuffer = null;
                } else {
                    pooledBuffer = pooled;
                }
            }


        }

@Override
    public void handleRequest(HttpServerExchange exchange) throws Exception {
        // TODO: add debug/warn log?
        // 400 if in case of no Host header or more than one: https://datatracker.ietf.org/doc/html/rfc7230#section-5.4
        // 400 if value violate rules. Host = uri-host [ ":" port ]
        // uri-host https://datatracker.ietf.org/doc/html/rfc3986#section-3.2.2
        // port https://datatracker.ietf.org/doc/html/rfc3986#section-3.2.3
        // NOTE: that 3.2.2 is NOT as restrictive as pure DNS it allows subdelims, percent etc by design as to not be
        // restricted to pure DNS, ALTHOUGH DNS compliant content is preferred.
        final HeaderMap headerMap = exchange.getRequestHeaders();
        final HeaderValues headerValues = headerMap.get(Headers.HOST);
        final HttpString protocol = exchange.getProtocol();

        if((protocol.equals(Protocols.HTTP_0_9) || protocol.equals(Protocols.HTTP_1_0))){
            if (headerValues == null) {
                //TODO: should we fake Host till we make it?
                next.handleRequest(exchange);
                return;
            }
            //else {
                //clients want to be good citizens and send it anyway.
                //fall through to below, first check will be false, but rest is the same as for HTTP1.1+
            //}
        }

        if (headerValues == null || headerValues.size() == 0) {
            // isEmpty - we assume http/https ? so authority is defined for this type, it cant be empty?
            terminate(exchange, STATUS_NO_HOST_HEADER);
            return;
        } else if (headerValues.size() > 1) {
            terminate(exchange, STATUS_TOO_MANY_HOST_HEADERS);
            return;
        }


        // parsing time.
        final String headerValue = headerValues.element();
        // uri-host [ ":" port ]
        // This is tricky, IP-Literal contain :, which is port delimiter in pair
        // Lets just try to take take care of port first
        final int rightBracketIndex = headerValue.lastIndexOf(']');
        final int lastColonIndex = headerValue.lastIndexOf(':');

        final String hostHeaderURI;
        // in case of IPv4, rightBracketIndex will be -1, in case of IPv6, it MUST be less than last :
        if (rightBracketIndex < lastColonIndex) {
            // we have port or potentially malformed IP Literal:
            // IP-literal = "[" ( IPv6address / IPvFuture ) "]" - without right bracket
            if (rightBracketIndex == -1 && headerValue.startsWith("[")) {
                // bad [ = 0, ] = -1, : = n+
                // good [ = 0, ] = n , : = n+x
                terminate(exchange, STATUS_MALFORMED_IP_LITERAL);
                return;
            }
            // we have valid host-uri with port
            final String portString = headerValue.substring(lastColonIndex + 1);
            try {
                int port = Integer.parseInt(portString);
                if (port <= 0 || port > 65535) {
                    // sanity check
                    // NOTE: 3.2.3 does not have provision like for IPv4 - decimal between 0-255.
                    // so this might be too restrictive
                    terminate(exchange, STATUS_MALFORMED_PORT);
                    return;
                }
                // fall through to uri-host checks
            } catch (NumberFormatException nfe) {
                terminate(exchange, STATUS_MALFORMED_PORT);
                return;
            }

            hostHeaderURI = headerValue.substring(0, lastColonIndex);
        } else {
            hostHeaderURI = headerValue;
        }

        // at this point we either have IP-Literal, IPv4 address or custom name
        if (rightBracketIndex > 0 && hostHeaderURI.indexOf('[') != 0) {
            // 1:2:4]*
            terminate(exchange, STATUS_MALFORMED_IP_LITERAL);
            return;
        } else if (rightBracketIndex > 0 && hostHeaderURI.indexOf('[') == 0) {
            // IPv6 or IPFuture
            // IP-literal = "[" ( IPv6address / IPvFuture ) "]"
            // IPvFuture = "v" 1*HEXDIG "." 1*( unreserved / sub-delims / ":" )
            final String debracked = hostHeaderURI.substring(1, hostHeaderURI.length() - 1);
            if (debracked.startsWith("v")) {
                final int dotIndex = debracked.indexOf(".");
                if (dotIndex < 2) {
                    // we need at least one HEX
                    terminate(exchange, STATUS_MALFORMED_IP_LITERAL);
                    return;
                }

                final String hex = debracked.substring(1, dotIndex);
                for (int i = 0; i < hex.length(); i++) {
                    final char c1 = hex.charAt(i);
                    if (!HEX_CHARACTERS[c1]) {
                        terminate(exchange, STATUS_MALFORMED_IP_LITERAL_BAD_CHARS);
                        return;
                    }
                }
                if (dotIndex + 1 >= debracked.length()) {
                    // we need some character behind dot.
                    terminate(exchange, STATUS_MALFORMED_IP_LITERAL);
                    return;
                }

                for (int i = dotIndex + 1; i < debracked.length(); i++) {
                    final char c = debracked.charAt(i);
                    if (!ALLOWED_IPv_FUTURE_CHARACTERS[c]) {
                        terminate(exchange, STATUS_MALFORMED_IP_LITERAL_BAD_CHARS);
                        return;
                    }
                }
            } else {
                // This will match IPv6 and IPv6 with embedded IPv4
                if (!IP6_EXACT.matcher(debracked).matches()) {
                    terminate(exchange, STATUS_MALFORMED_IP_LITERAL);
                    return;
                }
                // TODO: as in case of IPv6 do we need to vet some weir daddresses?
            }

        } else if (IP4_EXACT.matcher(hostHeaderURI).matches()) {
            // IPv4
            // NOTE: above will match only valid range 0-255, rest will fall through to reg-name, which is ok, since its
            // essentially
            // superset of IP, given DIGIT + "." ( unreserved )
        } else {
            // registered name can contain . and digits, so it technically overlap IPv4.
            // above wont cover -192.168.1.1/355.0.0.0, which technically is correct 'reg-name'
            // at this point we can really only check if its valid char or percent encoding.
            for (int index = 0; index < hostHeaderURI.length(); index++) {
                final char c = hostHeaderURI.charAt(index);
                if (c == '%') {
                    // we need at least two more that are HEX
                    if (index + 2 < hostHeaderURI.length()) {
                        char c1 = hostHeaderURI.charAt(++index);
                        char c2 = hostHeaderURI.charAt(++index);
                        if (!(HEX_CHARACTERS[c1] && HEX_CHARACTERS[c2])) {
                            terminate(exchange, STATUS_MALFORMED_IP_LITERAL_BAD_CHARS);
                            return;
                        }
                    } else {
                        // we dont have at least two chars(hex), so its not proper percent escape
                        terminate(exchange, STATUS_MALFORMED_IP_LITERAL);
                        return;
                    }
                } else if (!ALLOWED_REGNAME_CHARACTERS[c]) {
                    terminate(exchange, STATUS_MALFORMED_IP_LITERAL_BAD_CHARS);
                    return;
                }
                // valid
            }
        }
        // NOTE: at this point if userinfo("@") was present in host, it would have failed
        // we need only to check if Host header value is contained within URI if its absolute or authority
        if (exchange.isHostIncludedInRequestURI()) {
            if (!exchange.getRequestURI().contains(hostHeaderURI)) {
                terminate(exchange, STATUS_HOST_NO_MATCH);
                return;
            } else if (hostHeaderURI.isEmpty()) {
                terminate(exchange, STATUS_HOST_NO_MATCH);
                return;
            }
        }

        // in the end...
        next.handleRequest(exchange);
    }

public void handleEventWithNoRunningRequest(final ConduitStreamSourceChannel channel) {
        PooledByteBuffer existing = connection.getExtraBytes();
        if ((existing == null && connection.getOriginalSourceConduit().isReadShutdown()) || connection.getOriginalSinkConduit().isWriteShutdown()) {
            UndertowLogger.REQUEST_IO_LOGGER.debug("Connection is closing, cancelling handling of request");
            IoUtils.safeClose(connection);
            channel.suspendReads();
            return;
        }
        final PooledByteBuffer pooled;
        try {
            pooled = existing == null ? connection.getByteBufferPool().allocate() : existing;
        } catch (IllegalStateException e) {
            UndertowLogger.REQUEST_IO_LOGGER.debug("Connection is closing, cancelling handling of request", e);
            // shutdown started after previous if statement, so treat it like previous statement
            IoUtils.safeClose(connection);
            channel.suspendReads();
            return;
        }
        final ByteBuffer buffer = pooled.getBuffer();
        boolean free = true;

        try {
            int res;
            boolean bytesRead = false;
            do {
                if (existing == null) {
                    buffer.clear();
                    try {
                        res = channel.read(buffer);
                    } catch (IOException e) {
                        UndertowLogger.REQUEST_IO_LOGGER.debug("Error reading request", e);
                        IoUtils.safeClose(connection);
                        return;
                    }
                } else {
                    res = buffer.remaining();
                }

                if (res <= 0) {
                    if(bytesRead && parseTimeoutUpdater != null) {
                        parseTimeoutUpdater.failedParse();
                    }
                    handleFailedRead(channel, res);
                    return;
                } else {
                    bytesRead = true;
                }
                if (existing != null) {
                    existing = null;
                    connection.setExtraBytes(null);
                } else {
                    buffer.flip();
                }
                int begin = buffer.remaining();
                if(httpServerExchange == null) {
                    httpServerExchange = new HttpServerExchange(connection, maxEntitySize);
                }
                parser.handle(buffer, state, httpServerExchange);
                if (state.isComplete()) {
                    // [UNDERTOW-2082] NOTE: this should be used only for HTTP1.x
                    if(!Cookies.isCrumbsAssemplyDisabled()) {
                        Cookies.assembleCrumbs(httpServerExchange.getRequestHeaders());
                    }
                    //TODO: list type headers?
                }
                if (buffer.hasRemaining()) {
                    free = false;
                    connection.setExtraBytes(pooled);
                }
                int total = read + (begin - buffer.remaining());
                read = total;
                if (read > maxRequestSize) {
                    UndertowLogger.REQUEST_LOGGER.requestHeaderWasTooLarge(connection.getPeerAddress(), maxRequestSize);
                    sendBadRequestAndClose(connection.getChannel(), null);
                    return;
                }
            } while (!state.isComplete());
            if(parseTimeoutUpdater != null) {
                parseTimeoutUpdater.requestStarted();
            }
            connection.getOriginalSourceConduit().suspendReads();

            final HttpServerExchange httpServerExchange = this.httpServerExchange;
            httpServerExchange.setRequestScheme(connection.getSslSession() != null ? "https" : "http");
            this.httpServerExchange = null;
            requestStateUpdater.set(this, 1);

            if (recordRequestStartTime) {
                Connectors.setRequestStartTime(httpServerExchange);
            }

            if(httpServerExchange.getProtocol() == Protocols.HTTP_2_0) {
                free = handleHttp2PriorKnowledge(pooled, httpServerExchange);
                return;
            }

            if(!allowUnknownProtocols) {
                HttpString protocol = httpServerExchange.getProtocol();
                if(protocol != Protocols.HTTP_1_1 && protocol != Protocols.HTTP_1_0 && protocol != Protocols.HTTP_0_9) {
                    UndertowLogger.REQUEST_IO_LOGGER.debugf("Closing connection from %s due to unknown protocol %s", connection.getChannel().getPeerAddress(), protocol);
                    sendBadRequestAndClose(connection.getChannel(), new IOException());
                    return;
                }
            }
            HttpTransferEncoding.setupRequest(httpServerExchange);
            connection.setCurrentExchange(httpServerExchange);
            if(connectorStatistics != null) {
                connectorStatistics.setup(httpServerExchange);
            }
            if(connection.getSslSession() != null) {
                //TODO: figure out a better solution for this
                //in order to improve performance we do not generally suspend reads, instead we a CAS to detect when
                //data arrives while a request is running and suspend lazily, as suspend/resume is relatively expensive
                //however this approach does not work for SSL, as the underlying channel is not thread safe
                //so we just suspend every time (the overhead is likely much less than the general SSL overhead anyway)
                channel.suspendReads();
            }

            if(!Connectors.areRequestHeadersValid(httpServerExchange.getRequestHeaders())) {
                sendBadRequestAndClose(connection.getChannel(), UndertowMessages.MESSAGES.invalidHeaders());
                return;
            }

            //TODO: make this configurable/dynamic, to either allow users provide their own here or in chain
            Connectors.executeRootHandler(HostHeaderHandler.WRAPPER.wrap(connection.getRootHandler()), httpServerExchange);
        } catch (Throwable t) {
            sendBadRequestAndClose(connection.getChannel(), t);
            return;
        } finally {
            if (free) pooled.close();
        }
    }

